package ca.hccis.scuba.entity;

import ca.hccis.scuba.util.InputUtility;

/**
 * Represents a single scuba dive plan entry for the Scuba Dive Air Consumption
 * and Tank Planner.
 *
 * The diveId is auto generated by the Controller, it is not entered by the user.
 *
 * @author Jonathan Dumaguing
 * @since 20261015
 */
public class Dive {

    //Validation ranges for the numeric fields.
    public static final double HEIGHT_MIN = 100.0;
    public static final double HEIGHT_MAX = 250.0;
    public static final double WEIGHT_MIN = 30.0;
    public static final double WEIGHT_MAX = 250.0;
    public static final double DEPTH_MIN = 1.0;
    public static final double DEPTH_MAX = 40.0;
    public static final double TIME_MIN = 1.0;
    public static final double TIME_MAX = 240.0;

    private int diveId;
    private String diverName;
    private double heightCm;
    private double weightKg;
    private String gender;          // MALE / FEMALE
    private String ageGroup;        // AGE_10S, AGE_20S, AGE_30S, AGE_40S, AGE_50S_PLUS
    private double targetDepthMeters;
    private double plannedTimeMinutes;
    private String diveScenario;    // DRIFT, CAVE_WRECK, COUNTER_CURRENT

    public Dive() {
    }

    public Dive(int diveId, String diverName, double heightCm, double weightKg,
                String gender, String ageGroup, double targetDepthMeters,
                double plannedTimeMinutes, String diveScenario) {
        this.diveId = diveId;
        this.diverName = diverName;
        this.heightCm = heightCm;
        this.weightKg = weightKg;
        this.gender = gender;
        this.ageGroup = ageGroup;
        this.targetDepthMeters = targetDepthMeters;
        this.plannedTimeMinutes = plannedTimeMinutes;
        this.diveScenario = diveScenario;
    }

    /**
     * Gather the dive plan details using the console.
     *
     * @author Jonathan Dumaguing
     * @since 20261015
     */
    public void getInformation() {
        getInformation(false);
    }

    /**
     * Gather the dive plan details from the user.  Used by both add and edit, and
     * by both the console thread and the JOptionPane thread.
     *
     * The diver name is not asked here, it is collected first by the menu so the
     * duplicate name check can happen before the other fields are typed in.
     *
     * @param gui true to use JOptionPane, false to use the console
     * @author Jonathan Dumaguing
     * @since 20261015
     */
    public void getInformation(boolean gui) {
        heightCm = getValidDouble("Height (cm)", HEIGHT_MIN, HEIGHT_MAX, gui);
        weightKg = getValidDouble("Weight (kg)", WEIGHT_MIN, WEIGHT_MAX, gui);
        gender = getValidOption("Gender", new String[]{"MALE", "FEMALE"}, gui);
        ageGroup = getValidOption("Age Group",
                new String[]{"AGE_10S", "AGE_20S", "AGE_30S", "AGE_40S", "AGE_50S_PLUS"}, gui);
        targetDepthMeters = getValidDouble("Target Depth (meters)", DEPTH_MIN, DEPTH_MAX, gui);
        plannedTimeMinutes = getValidDouble("Planned Bottom Time (minutes)", TIME_MIN, TIME_MAX, gui);
        diveScenario = getValidOption("Dive Scenario",
                new String[]{"DRIFT", "CAVE_WRECK", "COUNTER_CURRENT"}, gui);
    }

    /**
     * Keep asking until the user enters a number inside the allowed range.
     *
     * @param prompt Prompt for the user
     * @param min Smallest value accepted
     * @param max Largest value accepted
     * @param gui true to use JOptionPane, false to use the console
     * @return A valid double entered by the user
     * @author Jonathan Dumaguing
     * @since 20261015
     */
    private double getValidDouble(String prompt, double min, double max, boolean gui) {

        String fullPrompt = prompt + " (" + min + " to " + max + ")";

        while (true) {
            String entered = InputUtility.getString(fullPrompt, gui).trim();
            try {
                double value = Double.parseDouble(entered);
                if (value < min || value > max) {
                    InputUtility.showMessage("Value must be between " + min + " and " + max + ".", gui);
                    continue;
                }
                return value;
            } catch (NumberFormatException e) {
                InputUtility.showMessage("'" + entered + "' is not a valid number.  Please try again.", gui);
            }
        }
    }

    /**
     * Keep asking until the user enters one of the allowed options.  The entry is
     * not case sensitive.
     *
     * @param prompt Prompt for the user
     * @param options Allowed values
     * @param gui true to use JOptionPane, false to use the console
     * @return The valid option in upper case
     * @author Jonathan Dumaguing
     * @since 20261015
     */
    private String getValidOption(String prompt, String[] options, boolean gui) {

        String fullPrompt = prompt + " (" + String.join(", ", options) + ")";

        while (true) {
            String value = InputUtility.getString(fullPrompt, gui).trim().toUpperCase();
            for (String option : options) {
                if (option.equals(value)) {
                    return value;
                }
            }
            InputUtility.showMessage("Invalid " + prompt.toLowerCase() + ".  Please try again.", gui);
        }
    }

    public int getDiveId() {
        return diveId;
    }

    public void setDiveId(int diveId) {
        this.diveId = diveId;
    }

    public String getDiverName() {
        return diverName;
    }

    public void setDiverName(String diverName) {
        this.diverName = diverName;
    }

    public double getHeightCm() {
        return heightCm;
    }

    public void setHeightCm(double heightCm) {
        this.heightCm = heightCm;
    }

    public double getWeightKg() {
        return weightKg;
    }

    public void setWeightKg(double weightKg) {
        this.weightKg = weightKg;
    }

    public String getGender() {
        return gender;
    }

    public void setGender(String gender) {
        this.gender = gender;
    }

    public String getAgeGroup() {
        return ageGroup;
    }

    public void setAgeGroup(String ageGroup) {
        this.ageGroup = ageGroup;
    }

    public double getTargetDepthMeters() {
        return targetDepthMeters;
    }

    public void setTargetDepthMeters(double targetDepthMeters) {
        this.targetDepthMeters = targetDepthMeters;
    }

    public double getPlannedTimeMinutes() {
        return plannedTimeMinutes;
    }

    public void setPlannedTimeMinutes(double plannedTimeMinutes) {
        this.plannedTimeMinutes = plannedTimeMinutes;
    }

    public String getDiveScenario() {
        return diveScenario;
    }

    public void setDiveScenario(String diveScenario) {
        this.diveScenario = diveScenario;
    }

    @Override
    public String toString() {
        return String.format(
                "Dive: diveId=%d, diverName='%s', height=%.1fcm, weight=%.1fkg, gender='%s', "
                        + "ageGroup='%s', depth=%.1fm, time=%.1fmin, scenario='%s'",
                diveId, diverName, heightCm, weightKg, gender, ageGroup,
                targetDepthMeters, plannedTimeMinutes, diveScenario);
    }
}
